<script setup>
import {computed,onMounted,ref} from 'vue'
import {api,useLearning} from '../useLearning.js'
import {artwork,icon} from '../assets.js'
const {state,refresh,notify,navigate}=useLearning()
const form=ref({name:'',daily_minutes:30,style:'',interests:[],study_period:'unspecified'}),busy=ref(false),error=ref(''),health=ref(null),checking=ref(false),runtime=ref(null),checkError=ref('')
const tags=['数学思维','编程与智能','阅读与写作','人文历史','科学与生活','艺术与设计','社会与现实','生活与成长']
const customInterest=ref('')
const allTags=computed(()=>[...new Set([...tags,...form.value.interests])])
const times=computed(()=>[...new Set([15,30,45,60,90,form.value.daily_minutes])].sort((a,b)=>a-b))
function toggle(tag){form.value.interests=form.value.interests.includes(tag)?form.value.interests.filter(t=>t!==tag):[...form.value.interests,tag]}
function addInterest(){const tag=customInterest.value.trim();if(!tag)return;if(form.value.interests.length>=12&&!form.value.interests.includes(tag)){error.value='最多选择12个兴趣方向。';return}if(!form.value.interests.includes(tag))form.value.interests.push(tag);customInterest.value=''}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await api('/profile',{method:'PATCH',body:form.value});await refresh();notify('学习偏好已保存。')}catch(e){error.value=e.message}finally{busy.value=false}}
async function check(){checking.value=true;checkError.value='';const [healthResult,pblResult]=await Promise.allSettled([api('/health'),api('/pbl/catalog')]);health.value=healthResult.status==='fulfilled'?healthResult.value:null;runtime.value=pblResult.status==='fulfilled'?pblResult.value.runtime:null;if(healthResult.status==='rejected')checkError.value='暂时无法读取服务状态，可以重新检查。';checking.value=false}
onMounted(()=>{const p=state.boot.profile;form.value={name:p.name,daily_minutes:p.daily_minutes,style:p.style,interests:p.interests||[],study_period:p.study_period||'unspecified'};check()})
</script>
<template><section class="settings-page-live"><div class="settings-page-grid"><form class="settings-main-form" @submit.prevent="save"><section><h2>基础信息</h2><p>这些设置用于当前学习空间。</p><div class="profile-information"><img :src="artwork.learner" alt="学习者头像"><div><label>你的称呼<input v-model="form.name" required maxlength="30"></label><label>每日学习时间<select v-model.number="form.daily_minutes"><option v-for="minutes in times" :key="minutes" :value="minutes">{{ minutes }} 分钟</option></select></label></div></div><label>希望怎样获得帮助<textarea v-model="form.style" rows="3" maxlength="200" placeholder="例如：先看一个具体例子，再解释概念；卡住时先给线索。"></textarea></label></section><section><h2>学习偏好</h2><p>可以选择感兴趣的方向，也可以暂时不选；创建目标不限于这些主题。</p><div class="settings-interest-tags"><button v-for="tag in allTags" :key="tag" type="button" :aria-pressed="form.interests.includes(tag)" :class="{active:form.interests.includes(tag)}" @click="toggle(tag)"><img v-if="form.interests.includes(tag)" :src="icon('check')" alt="">{{ tag }}</button></div><div class="settings-custom-interest"><input v-model="customInterest" aria-label="自定义兴趣方向" maxlength="30" placeholder="其他感兴趣的方向…" @keydown.enter.prevent="event=>{if(!event.isComposing)addInterest()}"><button type="button" class="secondary-button" :disabled="!customInterest.trim()" @click="addInterest">加入兴趣</button></div><fieldset class="settings-period"><legend>偏好的学习时段</legend><label v-for="[key,title,description] in [['unspecified','暂不设置','按当天安排'],['morning','上午','06:00 — 12:00'],['afternoon','下午','12:00 — 18:00'],['evening','晚上','18:00 — 24:00']]" :key="key" :class="{active:form.study_period===key}"><input v-model="form.study_period" type="radio" :value="key" name="study-period"><strong>{{ title }}</strong><small>{{ description }}</small></label></fieldset></section><p v-if="error" class="inline-error" role="alert">{{ error }}</p><footer><small>保存后生效，不会改写已经留下的作答与学习证据。</small><button class="primary-button" :disabled="busy">{{ busy?'保存中…':'保存学习偏好' }}</button></footer></form><aside><section class="settings-mentor-card"><h2>与 AI 导师同行</h2><p>让讲解方式，逐步贴近你的学习习惯。</p><img :src="artwork.mentor" alt="林知导师"></section><section class="studio-side-card settings-export-card"><img src="/assets/competition-v1/settings/data-box.png.webp" alt=""><h2>数据导出</h2><p>保留自己的目标、笔记、资料与学习记录。</p><a href="/api/export" download><img :src="icon('box')" alt=""><span>导出完整 JSON 记录</span><img :src="icon('chevron-right')" alt=""></a><a href="/api/export/markdown" download><img :src="icon('file-text')" alt=""><span>导出 Markdown 笔记</span><img :src="icon('chevron-right')" alt=""></a></section><section class="studio-side-card settings-service-card"><div class="section-heading"><h2>服务连接</h2><button type="button" class="text-button" :disabled="checking" @click="check">{{ checking?'检查中…':'重新检查' }}</button></div><dl class="service-check-list"><div><dt>网站服务</dt><dd :class="{available:health?.ok}">{{ health?.ok?'可以连接':'等待检查' }}</dd></div><div><dt>林知答疑</dt><dd>{{ health?.model?.configured?'已配置，提问时连接':'尚未配置' }}</dd></div><div><dt>代码执行</dt><dd :class="runtime?.available?'available':'unavailable'">{{ runtime?.available?'执行服务可连接':runtime?'暂未连接':'状态尚未取得' }}</dd></div></dl><p v-if="checkError" role="status">{{ checkError }}</p><small>未连接的功能会明确提示，已经保存的学习内容可以继续查看。</small></section></aside></div></section></template>
